from itertools import product

def kth_sequence(n, k):
    total_sequences = (n-1) ** (n-1)
    if k > total_sequences // (n-1) or k % (n-1) == 0:
        return "NO"

    valid_sequences = []
    for seq in product(range(1, n), repeat=n-1):
        if all(sum(seq[i:i+j]) % n != 0 for j in range(1, n)):
