    mod = n - 1
    result = [0] * (n - 1)

    def backtrack(index, current_sum, last_used):
        if index == n - 1:
            result[index] = mod - current_sum
            return True
        for next_petals in range(1, n):
            if next_petals != last_used and (current_sum + next_petals) % mod != 0:
                if backtrack(index + 1, current_sum + next_petals, next_petals):
                    return True
        return False

    # Adjust k because the sequences start from 1 instead of 0
    k -= 1
    count = 0
    for first_petals in range(1, n):
        if first_petals != mod and first_petals % mod != 0:
            if backtrack(1, first_petals, first_petals):
                count += 1
                if count == k + 1:
