def count_valid_sequences(n, k):
    def is_valid(seq):
        for i in range(len(seq)):
            for j in range(i + 1, len(seq) + 1):
                if sum(seq[i:j]) % n == 0:
                    return False
        return True

    def count_leading_valids():
        total = 0
        for i in range(1, n):
            total += factorial(n - 1) // (factorial(i) * factorial(n - 1 - i))
        return total

    leading_valids = count_leading_valids()
    k -= leading_valids
    seq = [1] * (n - 1)
    used = set(range(1, n))

    for i in range(n - 2, -1, -1):
        total = factorial(i) * factorial(n - 2 - i)
        for p in range(1, n):
            if p not in used:
                if k <= total:
                    seq[i] = p
                    used.remove(p)
                    break
                else:
                    k -= total

    return seq

