def generate_sequence(n, k):
    if n == 2:
        return [1] * (k - 1)

    def count_sequences(m, p):
        if m == 1:
            return p
        if m % 2 == 0:
            return count_sequences(m // 2, p * 2)
        else:
            return count_sequences((m - 1) // 2, p * 3 + 1)

    def find_sequence(m, k, seq):
        if m == 1:
            seq.append(k)
            return
        if k <= count_sequences(m // 2, len(seq)):
            find_sequence(m // 2, k, seq)
        else:
            k -= count_sequences(m // 2, len(seq))
            if m % 2 == 0:
                find_sequence((m - 1) // 2, k, seq)
            else:
                seq.append(1)
                find_sequence((m - 1) // 2, k - count_sequences((m - 1) // 2, len(seq)), seq)

    m = 2 ** (len(bin(n)) - 3)
    seq = []
    find_sequence(m, k, seq)
    return seq

