def calculate_combinations(n, r):
    return factorial(n) // (factorial(r) * factorial(n - r))

def find_kth_sequence(n, k):
    def count_valid_sequences(max_petals, length):
        if length == 1:
            return max_petals
        total_sequences = 0
        for petals in range(1, max_petals + 1):
            total_sequences += count_valid_sequences(petals - 1, length - 1)
        return total_sequences

    def get_next_max_petals(current_sum, previous_petals):
        next_max_petals = current_sum - previous_petals
        while next_max_petals >= 1 and (current_sum % n == 0 or previous_petals % n == 0):
            next_max_petals -= 1
        return next_max_petals if next_max_petals > 0 else 1

    sequence = []
    remaining_length = n - 1
    current_sum = 0

    while remaining_length > 0:
        max_petals = get_next_max_petals(current_sum, sequence[-1] if sequence else 0)
        combinations = calculate_combinations(max_petals, remaining_length)

        if k <= combinations:
            sequence.append(max_petals)
            current_sum += max_petals
            remaining_length -= 1
        else:
            k -= combinations
            current_sum += sequence.pop()

    return ' '.join(map(str, sequence[::-1]))

