def find_kth_sequence(n, k):
    def count_valid_sequences(length):
        if length == 0:
            return 1
        return sum(comb(length - 1, i) * pow(-1, i) for i in range(1, n))

    length = 1
    while count_valid_sequences(length) < k:
        length += 1

    result = []
    remaining = k - 1

    for i in range(n-1, 0, -1):
        count = 0
        while True:
            new_count = count_valid_sequences(length - i)
            if remaining >= new_count:
                count += new_count
                remaining -= new_count
            else:
                break
        result.append(str(i + count // (comb(length - i, i - 1))))
        length -= i

    return ' '.join(result[::-1])

